=== src/client.js
// HTTP client for the Syncbox server API (see syncbox-openapi.yaml).
//
// Built on node:http rather than fetch(): fetch refuses a list of "bad
// ports" (6000, 10080, ...) that a Syncbox server may well listen on.

import fs from 'node:fs';
import http from 'node:http';
import https from 'node:https';

export class RequestError extends Error {
  constructor(message) {
    super(message);
    this.name = 'RequestError';
  }
}

export class SyncboxClient {
  /** @param {URL} server  base URL; may include a path prefix */
  constructor(server) {
    this.server = server;
    // Without the trailing slash, so that appending "/blobs" works for both
    // http://host:8080 and http://host/prefix/.
    this.base = server.origin + server.pathname.replace(/\/+$/, '');
  }

  /**
   * Lists blobs stored on the server.
   *
   * @returns {Promise<Array<{ key: string, sha256: string, size: number, modified_at: string }>>}
   * @throws {RequestError}
   */
  async list() {
    const res = await this.#request('GET', `${this.base}/blobs`);
    if (res.status !== 200) {
      throw new RequestError(`GET /blobs: ${describeFailure(res)}`);
    }
    let blobs;
    try {
      blobs = JSON.parse(res.body.toString('utf8'));
    } catch (err) {
      throw new RequestError(`GET /blobs: response is not valid JSON: ${err.message}`);
    }
    if (!Array.isArray(blobs) || !blobs.every((b) => typeof b?.key === 'string' && typeof b?.sha256 === 'string')) {
      throw new RequestError('GET /blobs: response is not a list of blobs');
    }
    return blobs;
  }

  /**
   * Uploads the contents of a local file as the blob `key`, replacing any
   * blob already stored under it.
   *
   * @param {string} key
   * @param {string} file  path of the local file
   * @returns {Promise<{ key: string, sha256: string, size: number }>}
   * @throws {RequestError} if the server cannot be reached or rejects the upload
   * @throws {Error} if the file cannot be read
   */
  async put(key, file) {
    // Sent chunked rather than with a Content-Length taken from stat(): a
    // file that shrinks while being read would leave the server waiting for
    // bytes that never come.
    const res = await this.#request('PUT', `${this.base}/blobs/${encodeKey(key)}`, {
      headers: { 'Content-Type': 'application/octet-stream' },
      body: fs.createReadStream(file),
    });
    if (res.status !== 201) {
      throw new RequestError(`PUT ${key}: ${describeFailure(res)}`);
    }
    try {
      return JSON.parse(res.body.toString('utf8'));
    } catch (err) {
      throw new RequestError(`PUT ${key}: response is not valid JSON: ${err.message}`);
    }
  }

  /**
   * @param {string} method
   * @param {string} url
   * @param {{ headers?: Record<string, string>, body?: import('node:stream').Readable }} [options]
   * @returns {Promise<{ status: number, statusText: string, body: Buffer }>}
   */
  #request(method, url, { headers = {}, body } = {}) {
    return new Promise((resolve, reject) => {
      const transport = url.startsWith('https:') ? https : http;
      const req = transport.request(url, { method, headers }, (res) => {
        const chunks = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => {
          // The server may answer (e.g. 400) without reading the whole body.
          body?.destroy();
          resolve({ status: res.statusCode, statusText: res.statusMessage, body: Buffer.concat(chunks) });
        });
        res.on('error', (err) => reject(this.#networkError(err)));
      });
      req.on('error', (err) => {
        body?.destroy();
        reject(this.#networkError(err));
      });
      if (!body) {
        req.end();
        return;
      }
      body.on('error', (err) => {
        // A local read error, not a network one: report it as it is.
        reject(err);
        req.destroy();
      });
      body.pipe(req);
    });
  }

  #networkError(err) {
    // With several addresses to try (::1 and 127.0.0.1 for localhost) the
    // error is an AggregateError whose own message may be empty.
    const detail = err.errors?.length ? err.errors.map((e) => e.message).join('; ') : err.message || err.code;
    return new RequestError(`cannot reach server ${this.server.href}: ${detail}`);
  }
}

/**
 * Percent-encodes a key for use in a URL path. Each segment is encoded on its
 * own so the "/" separators stay as they are.
 *
 * @param {string} key
 * @returns {string}
 */
export function encodeKey(key) {
  return key.split('/').map(encodeURIComponent).join('/');
}

function describeFailure(res) {
  const text = res.body.toString('utf8');
  let detail;
  try {
    detail = JSON.parse(text)?.error ?? text;
  } catch {
    detail = text;
  }
  detail = String(detail).trim().slice(0, 200);
  return `server answered ${res.status} ${res.statusText}${detail ? ` (${detail})` : ''}`;
}
=== src/client-main.js
#!/usr/bin/env node
// Entry point of the `syncbox` CLI: syncbox <command> <dir> --server <url>

import { ConfigError, USAGE, parseClientArgs } from './client-config.js';
import { RequestError, SyncboxClient } from './client.js';
import { push } from './push.js';

const EXIT_FAILURE = 1;
const EXIT_USAGE = 2;

async function main() {
  let config;
  try {
    config = parseClientArgs(process.argv.slice(2), process.env);
  } catch (err) {
    if (err instanceof ConfigError) {
      console.error(`syncbox: ${err.message}\n\n${USAGE}`);
      return EXIT_USAGE;
    }
    throw err;
  }

  if (config.help) {
    console.log(USAGE);
    return 0;
  }

  const client = new SyncboxClient(config.server);
  switch (config.command) {
    case 'push': {
      const { uploaded, upToDate } = await push({
        dir: config.dir,
        client,
        log: (line) => console.log(line),
        warn: (line) => console.error(`syncbox: ${line}`),
      });
      console.log(`push: ${uploaded.length} uploaded, ${upToDate.length} already up to date`);
      return 0;
    }
    default:
      console.error(`syncbox: the ${config.command} command is not implemented yet; only push is available`);
      return EXIT_FAILURE;
  }
}

main().then(
  (code) => {
    process.exitCode = code;
  },
  (err) => {
    // Expected failures (server unreachable or refusing, unreadable files)
    // get their message only; anything else gets the stack too.
    const expected = err instanceof RequestError || typeof err?.code === 'string';
    console.error(`syncbox: ${expected ? err.message : err?.stack ?? err}`);
    process.exitCode = EXIT_FAILURE;
  },
);
=== src/push.js
import { listFiles, sha256File } from './local-files.js';

/**
 * Uploads every file under `dir` that the server lacks or holds with
 * different contents. Files whose SHA-256 matches the server's copy are not
 * sent again. Nothing is deleted on either side. Stops at the first failure.
 *
 * @param {{
 *   dir: string,
 *   client: import('./client.js').SyncboxClient,
 *   log?: (line: string) => void,   progress, one line per uploaded file
 *   warn?: (line: string) => void,  files left out
 * }} options
 * @returns {Promise<{ uploaded: string[], upToDate: string[] }>} keys
 */
export async function push({ dir, client, log = () => {}, warn = () => {} }) {
  const files = await listFiles(dir, {
    onSkip: (relPath, reason) => warn(`skipping ${relPath}: ${reason}`),
  });
  const remote = new Map((await client.list()).map((blob) => [blob.key, blob.sha256]));

  const uploaded = [];
  const upToDate = [];
  for (const { key, path } of files) {
    if (remote.get(key) === (await sha256File(path))) {
      upToDate.push(key);
      continue;
    }
    await client.put(key, path);
    uploaded.push(key);
    log(`uploaded ${key}`);
  }
  return { uploaded, upToDate };
}
=== src/local-files.js
// The client's view of a local directory: which files it holds, under which
// keys, with which contents.

import { createHash } from 'node:crypto';
import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';

// ignoreBOM keeps a leading U+FEFF, which is part of the name.
const utf8 = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true });

/**
 * Lists the regular files under `root`, recursively, with their keys: the
 * path relative to `root` with "/" as the separator, the same convention the
 * server uses. Symbolic links and special files are not followed or read;
 * neither are names that are not valid UTF-8, which no key can express.
 * Each of those is reported through `onSkip` instead.
 *
 * @param {string} root
 * @param {{ onSkip?: (relPath: string, reason: string) => void }} [options]
 * @returns {Promise<Array<{ key: string, path: string }>>} sorted by key
 * @throws {Error} if `root` is not a readable directory
 */
export async function listFiles(root, { onSkip = () => {} } = {}) {
  const stat = await fsp.stat(root);
  if (!stat.isDirectory()) {
    const err = new Error(`not a directory: ${root}`);
    err.code = 'ENOTDIR';
    throw err;
  }
  const files = [];
  await walk(root, [], files, onSkip);
  return files.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
}

async function walk(dir, prefix, out, onSkip) {
  // Names as raw bytes, so that one which is not valid UTF-8 is noticed
  // instead of silently becoming U+FFFD.
  const entries = await fsp.readdir(dir, { withFileTypes: true, encoding: 'buffer' });
  for (const entry of entries) {
    let name;
    try {
      name = utf8.decode(entry.name);
    } catch {
      onSkip([...prefix, entry.name.toString()].join('/'), 'file name is not valid UTF-8');
      continue;
    }
    const segments = [...prefix, name];
    const full = path.join(dir, name);
    if (entry.isDirectory()) {
      await walk(full, segments, out, onSkip);
    } else if (entry.isFile()) {
      out.push({ key: segments.join('/'), path: full });
    } else if (entry.isSymbolicLink()) {
      onSkip(segments.join('/'), 'symbolic link');
    } else {
      onSkip(segments.join('/'), 'not a regular file');
    }
  }
}

/**
 * @param {string} file
 * @returns {Promise<string>} SHA-256 of the file's contents, in hex
 */
export async function sha256File(file) {
  const hash = createHash('sha256');
  for await (const chunk of fs.createReadStream(file)) {
    hash.update(chunk);
  }
  return hash.digest('hex');
}
=== src/client-config.js
// Client command line: syncbox <command> <dir> --server <url>.
// --server takes precedence over the SYNCBOX_SERVER environment variable.

export const COMMANDS = ['push', 'pull', 'status', 'sync'];

export const USAGE = `Usage: syncbox <command> <dir> --server <url>

Commands:
  push    Upload files from <dir> that are missing on the server or differ from it
  pull    Download files from the server that are missing in <dir> or differ (not implemented yet)
  status  Show what push/pull would transfer, changing nothing (not implemented yet)
  sync    Two-way sync between <dir> and the server (not implemented yet)

Options:
  --server <url>  Base URL of the Syncbox server, e.g. http://127.0.0.1:8080 (required).
                  Env: SYNCBOX_SERVER
  -h, --help      Show this help and exit.`;

export class ConfigError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ConfigError';
  }
}

/**
 * Parses client arguments.
 *
 * @param {string[]} argv  arguments without the node binary and script path
 * @param {Record<string, string | undefined>} env
 * @returns {{ help: true } | { help: false, command: string, dir: string, server: URL }}
 * @throws {ConfigError} on missing or invalid arguments
 */
export function parseClientArgs(argv, env = {}) {
  const positional = [];
  let server;

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];

    if (arg === '-h' || arg === '--help') {
      return { help: true };
    }
    if (arg === '--') {
      positional.push(...argv.slice(i + 1));
      break;
    }
    if (arg === '--server') {
      if (i + 1 >= argv.length) {
        throw new ConfigError('--server requires a value');
      }
      server = argv[++i];
      continue;
    }
    if (arg.startsWith('--server=')) {
      server = arg.slice('--server='.length);
      continue;
    }
    // A lone "-" is not an option, so it can name a directory.
    if (arg.startsWith('-') && arg !== '-') {
      throw new ConfigError(`unknown option: ${arg}`);
    }
    positional.push(arg);
  }

  const [command, dir, ...extra] = positional;
  if (command === undefined) {
    throw new ConfigError('a command is required');
  }
  if (!COMMANDS.includes(command)) {
    throw new ConfigError(`unknown command: ${command}`);
  }
  if (dir === undefined || dir === '') {
    throw new ConfigError(`${command} requires a directory`);
  }
  if (extra.length > 0) {
    throw new ConfigError(`unexpected argument: ${extra[0]}`);
  }

  // Empty strings count as "not set", as in the server's configuration.
  const rawServer = [server, env.SYNCBOX_SERVER].find((v) => v !== undefined && v !== '');
  if (rawServer === undefined) {
    throw new ConfigError('server URL is required: pass --server <url> or set SYNCBOX_SERVER');
  }

  return { help: false, command, dir, server: parseServerUrl(rawServer) };
}

function parseServerUrl(raw) {
  let url;
  try {
    url = new URL(raw);
  } catch {
    throw new ConfigError(`invalid server URL: ${JSON.stringify(raw)} (expected e.g. http://127.0.0.1:8080)`);
  }
  if (url.protocol !== 'http:' && url.protocol !== 'https:') {
    throw new ConfigError(`invalid server URL: ${JSON.stringify(raw)} (only http and https are supported)`);
  }
  if (url.search !== '' || url.hash !== '') {
    throw new ConfigError(`invalid server URL: ${JSON.stringify(raw)} (must not have a query or fragment)`);
  }
  return url;
}
=== README.md
# Syncbox

Self-hosted file storage with sync: an HTTP server plus a CLI client.
The contract lives in [SYNCBOX-SPEC.md](SYNCBOX-SPEC.md) and
[syncbox-openapi.yaml](syncbox-openapi.yaml).

Implementation: JavaScript on Node.js 20 with no npm dependencies. Everything
runs in Docker (`node:20-alpine`) through docker compose, so the host
only needs Docker with the compose plugin.

## Running

```sh
./run-server --data-dir ./data --port 8080   # foreground; Ctrl+C / SIGTERM stops it
curl http://127.0.0.1:8080/healthz           # {"status":"ok"}
curl -X PUT --data-binary @file.txt http://127.0.0.1:8080/blobs/docs/file.txt  # 201 {"key","sha256","size"}
curl http://127.0.0.1:8080/blobs/docs/file.txt                                # 200 + bytes, 404 if missing
curl -X DELETE http://127.0.0.1:8080/blobs/docs/file.txt                      # 204 no body, 404 if missing
curl http://127.0.0.1:8080/blobs             # 200 [{"key","size","sha256","modified_at"}], sorted by key; [] if empty
./run-client push ./mydir --server http://127.0.0.1:8080  # upload new and changed files
./run-tests                                  # full test suite, non-zero exit on failure
```

`run-server` also reads `SYNCBOX_DATA_DIR` / `SYNCBOX_PORT`; flags take
precedence. The data directory is created if missing and bind-mounted into
the container; files are written with the invoking user's UID/GID.

## Client

`run-client <push|pull|status|sync> <dir> --server <url>` runs the `syncbox`
CLI (`bin/syncbox`) in a container. `--server` can also come from
`SYNCBOX_SERVER`; the flag takes precedence. `<dir>` must exist. It is
bind-mounted read-only, and the container runs as the invoking user. The container
shares the host's network, so `--server` means the same as on the host
(`http://127.0.0.1:<port>` reaches a server started by `run-server`).

`push` walks `<dir>` recursively and keys each regular file by its relative
POSIX path (`docs/readme.txt`). It fetches `GET /blobs` and `PUT`s every file
whose SHA-256 is missing from the server or differs from the server's. Files
identical to the server's copy are not sent, and nothing is deleted on either
side. Symbolic links, special files and names that are not valid UTF-8 are
skipped with a note on stderr. stdout gets one `uploaded <key>` line per upload
and a summary. Exit codes: `0` success, `1` failure (message on stderr; push
stops at the first failed request), `2` invalid arguments. `pull`, `status`
and `sync` are accepted but not implemented yet: they exit `1` with a
message saying so.

`docker compose run` does not pass signals on to the container. So
`run-client` gives the client a TTY when it runs in a terminal, which lets
Ctrl+C reach the client itself. Without a terminal, the streams stay separate,
and a client whose wrapper is killed runs to completion.

## Keys

A key is a relative POSIX path, percent-decoded from the URL (`%2F` counts as
`/`). `PUT`, `GET` and `DELETE` answer `400` for a key that is empty, absolute,
contains an empty, `.` or `..` segment, a NUL, invalid UTF-8 or a lone
surrogate, or a segment over 255 bytes. Independently of that, the store
resolves every key to a path on disk and refuses it unless the result lies
strictly inside the blob root, both lexically and after following any
symlinks found in the data directory (the server never creates symlinks; a
symlink as the key itself is not treated as a blob).

## Atomic writes

`PUT` streams the body into `<data-dir>/tmp/<random>.part`, fsyncs it and
renames it to `<data-dir>/blobs/<key>`. Both live on the same mount (checked at
startup; the server refuses to start otherwise), so the rename atomically
replaces the old blob: a concurrent `GET` returns either the old or the new
contents in full, never a mix, and parallel `PUT`s to one key leave exactly one
complete version (the last rename wins). Files in `tmp/` are never listed or
reachable by any key. A failed or aborted upload removes its temp file;
leftovers from a crash are removed at the next startup, and unfinished uploads
are discarded on shutdown.

## Layout

| Path                   | Purpose                                                   |
| ---------------------- | --------------------------------------------------------- |
| `src/server-main.js`   | server entry point (args, data dir checks, signals)       |
| `src/config.js`        | flag/env parsing                                          |
| `src/server.js`        | HTTP routing and handlers                                 |
| `src/blobs.js`         | blob key validation and on-disk storage                   |
| `bin/syncbox`          | client executable (runs `src/client-main.js`)             |
| `src/client-config.js` | client argument parsing                                   |
| `src/client.js`        | HTTP client for the server API                            |
| `src/local-files.js`   | walking and hashing the local directory                   |
| `src/push.js`          | the push command                                          |
| `test/`                | `node:test` suites (unit + spawned-process integration)   |
| `Dockerfile`           | `server`, `client` and `test` build targets               |
| `compose.yaml`         | the only place where Docker build/run options are defined |
| `run-server`, `run-client`, `run-tests` | wrappers required by the spec            |
