// push() against a real Syncbox server running in-process on loopback.

import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import fs from 'node:fs/promises';
import http from 'node:http';
import net from 'node:net';
import os from 'node:os';
import path from 'node:path';
import { after, afterEach, before, beforeEach, describe, it } from 'node:test';

import { RequestError, SyncboxClient, encodeKey } from '../src/client.js';
import { push } from '../src/push.js';
import { createServer } from '../src/server.js';

const sha256 = (data) => createHash('sha256').update(data).digest('hex');

async function listen(server) {
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  return `http://127.0.0.1:${server.address().port}`;
}

async function close(server) {
  server.closeAllConnections();
  await new Promise((resolve) => server.close(resolve));
}

async function writeTree(root, files) {
  for (const [rel, content] of Object.entries(files)) {
    await fs.mkdir(path.dirname(path.join(root, rel)), { recursive: true });
    await fs.writeFile(path.join(root, rel), content);
  }
}

describe('push', () => {
  let tmp;
  let server;
  let baseUrl;
  let client;
  let dir;
  let requests;

  before(async () => {
    tmp = await fs.mkdtemp(path.join(os.tmpdir(), 'syncbox-push-'));
  });

  after(async () => {
    await fs.rm(tmp, { recursive: true, force: true });
  });

  let serial = 0;

  beforeEach(async () => {
    const name = `case-${++serial}`;
    dir = path.join(tmp, name, 'local');
    await fs.mkdir(dir, { recursive: true });
    server = createServer({ dataDir: path.join(tmp, name, 'data') });
    // Every request the server sees, as "METHOD path".
    requests = [];
    server.on('request', (req) => requests.push(`${req.method} ${req.url}`));
    baseUrl = await listen(server);
    client = new SyncboxClient(new URL(baseUrl));
  });

  afterEach(async () => {
    await close(server);
  });

  const puts = () => requests.filter((r) => r.startsWith('PUT '));

  async function serverBlobs() {
    const res = await fetch(`${baseUrl}/blobs`);
    return Object.fromEntries((await res.json()).map((b) => [b.key, b.sha256]));
  }

  async function serverContent(key) {
    const res = await fetch(`${baseUrl}/blobs/${encodeKey(key)}`);
    assert.equal(res.status, 200, key);
    return Buffer.from(await res.arrayBuffer());
  }

  it('uploads every file of a directory tree, byte for byte', async () => {
    const files = {
      'readme.txt': 'hello\n',
      'docs/guide.md': '# Guide\n',
      'docs/deep/nested/data.bin': Buffer.from([0, 1, 2, 0xfe, 0xff, 0x0a, 0x0d]),
      'empty': '',
      '.hidden/.dotfile': 'dot',
      'with space/ünï ?#%&+;=.txt': 'odd name',
      'big.bin': Buffer.alloc(5 * 1024 * 1024 + 3, 0x5a),
    };
    await writeTree(dir, files);

    const log = [];
    const result = await push({ dir, client, log: (line) => log.push(line) });

    const keys = Object.keys(files).sort();
    assert.deepEqual(result.uploaded, keys);
    assert.deepEqual(result.upToDate, []);
    assert.deepEqual(log, keys.map((k) => `uploaded ${k}`));
    assert.deepEqual(
      await serverBlobs(),
      Object.fromEntries(keys.map((k) => [k, sha256(Buffer.from(files[k]))])),
    );
    for (const key of keys) {
      assert.deepEqual(await serverContent(key), Buffer.from(files[key]), key);
    }
  });

  it('does not upload files that are already on the server with the same contents', async () => {
    await writeTree(dir, { 'a.txt': 'a', 'sub/b.txt': 'b', 'c.txt': 'c' });
    await push({ dir, client });
    requests.length = 0;

    const result = await push({ dir, client });
    assert.deepEqual(result.uploaded, []);
    assert.deepEqual(result.upToDate, ['a.txt', 'c.txt', 'sub/b.txt']);
    assert.deepEqual(requests, ['GET /blobs']);
  });

  it('uploads only the files that are new or changed', async () => {
    await writeTree(dir, { 'same.txt': 'same', 'changed.txt': 'old', 'sub/also-same.txt': 'x' });
    await push({ dir, client });
    requests.length = 0;

    await writeTree(dir, { 'changed.txt': 'new contents', 'sub/new.txt': 'brand new' });
    const result = await push({ dir, client });

    assert.deepEqual(result.uploaded, ['changed.txt', 'sub/new.txt']);
    assert.deepEqual(result.upToDate, ['same.txt', 'sub/also-same.txt']);
    assert.deepEqual(puts(), ['PUT /blobs/changed.txt', 'PUT /blobs/sub/new.txt']);
    assert.deepEqual(await serverContent('changed.txt'), Buffer.from('new contents'));
    assert.deepEqual(await serverContent('sub/new.txt'), Buffer.from('brand new'));
  });

  it('compares by SHA-256, not by size', async () => {
    // Same key and size on both sides, different bytes.
    await fetch(`${baseUrl}/blobs/f.txt`, { method: 'PUT', body: 'aaaa' });
    await writeTree(dir, { 'f.txt': 'bbbb' });
    requests.length = 0;

    const result = await push({ dir, client });
    assert.deepEqual(result.uploaded, ['f.txt']);
    assert.deepEqual(puts(), ['PUT /blobs/f.txt']);
    assert.deepEqual(await serverContent('f.txt'), Buffer.from('bbbb'));
  });

  it('leaves blobs that exist only on the server alone', async () => {
    await fetch(`${baseUrl}/blobs/server-only.txt`, { method: 'PUT', body: 'keep me' });
    await writeTree(dir, { 'local.txt': 'local' });

    await push({ dir, client });
    assert.deepEqual(Object.keys(await serverBlobs()), ['local.txt', 'server-only.txt']);
    assert.deepEqual(await serverContent('server-only.txt'), Buffer.from('keep me'));
  });

  it('percent-encodes each key segment', async () => {
    await writeTree(dir, { 'a b/%2F?#/ü.txt': 'x' });
    await push({ dir, client });
    assert.deepEqual(puts(), [`PUT /blobs/a%20b/%252F%3F%23/%C3%BC.txt`]);
    assert.deepEqual(Object.keys(await serverBlobs()), ['a b/%2F?#/ü.txt']);
  });

  it('skips symbolic links, reporting them', async () => {
    await writeTree(dir, { 'real.txt': 'r' });
    await fs.symlink('real.txt', path.join(dir, 'link.txt'));
    const warnings = [];
    const result = await push({ dir, client, warn: (line) => warnings.push(line) });
    assert.deepEqual(result.uploaded, ['real.txt']);
    assert.deepEqual(warnings, ['skipping link.txt: symbolic link']);
  });

  it('accepts a server URL with a trailing slash', async () => {
    await writeTree(dir, { 'a.txt': 'a' });
    await push({ dir, client: new SyncboxClient(new URL(`${baseUrl}/`)) });
    assert.deepEqual(puts(), ['PUT /blobs/a.txt']);
  });

  it('fails when the directory does not exist, before contacting the server', async () => {
    await assert.rejects(push({ dir: path.join(dir, 'missing'), client }), { code: 'ENOENT' });
    assert.deepEqual(requests, []);
  });

  it('fails with the server\'s reason when an upload is rejected', async () => {
    // "clash" is a blob on the server, so "clash/inner.txt" cannot be stored.
    await fetch(`${baseUrl}/blobs/clash`, { method: 'PUT', body: 'file' });
    await writeTree(dir, { 'clash/inner.txt': 'x' });
    await assert.rejects(push({ dir, client }), (err) => {
      assert.ok(err instanceof RequestError);
      assert.match(err.message, /^PUT clash\/inner\.txt: server answered 400 Bad Request \(invalid key: .+\)$/);
      return true;
    });
  });
});

describe('push to a server that misbehaves', () => {
  let tmp;

  before(async () => {
    tmp = await fs.mkdtemp(path.join(os.tmpdir(), 'syncbox-push-err-'));
    await fs.writeFile(path.join(tmp, 'a.txt'), 'a');
  });

  after(async () => {
    await fs.rm(tmp, { recursive: true, force: true });
  });

  it('fails promptly when nothing listens at the URL', async () => {
    const probe = net.createServer();
    const port = await new Promise((resolve) => probe.listen(0, '127.0.0.1', () => resolve(probe.address().port)));
    await new Promise((resolve) => probe.close(resolve));

    const client = new SyncboxClient(new URL(`http://127.0.0.1:${port}`));
    await assert.rejects(push({ dir: tmp, client }), (err) => {
      assert.ok(err instanceof RequestError);
      assert.match(err.message, new RegExp(`^cannot reach server http://127\\.0\\.0\\.1:${port}/: .*ECONNREFUSED`));
      return true;
    });
  });

  for (const [what, status, body] of [
    ['an error status', 500, '{"error":"internal server error"}'],
    ['something other than JSON', 200, '<html>proxy page</html>'],
    ['JSON that is not a list of blobs', 200, '{"key":"a.txt"}'],
  ]) {
    it(`fails when GET /blobs answers with ${what}`, async () => {
      const server = http.createServer((req, res) => {
        res.writeHead(status, { 'Content-Type': 'application/json' });
        res.end(body);
      });
      const client = new SyncboxClient(new URL(await listen(server)));
      try {
        await assert.rejects(push({ dir: tmp, client }), (err) => {
          assert.ok(err instanceof RequestError);
          assert.match(err.message, /^GET \/blobs: /);
          return true;
        });
      } finally {
        await close(server);
      }
    });
  }
});
// End-to-end tests of the `syncbox` executable: spawns bin/syncbox as a real
// process against a server running in-process on loopback.

import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
import fs from 'node:fs/promises';
import net from 'node:net';
import os from 'node:os';
import path from 'node:path';
import { after, before, describe, it } from 'node:test';
import { fileURLToPath } from 'node:url';

import { createServer } from '../src/server.js';

const SYNCBOX = fileURLToPath(new URL('../bin/syncbox', import.meta.url));

// Environment without any SYNCBOX_* variables inherited from the test runner.
const CLEAN_ENV = Object.fromEntries(Object.entries(process.env).filter(([k]) => !k.startsWith('SYNCBOX_')));

function run(args, env = {}) {
  return new Promise((resolve, reject) => {
    const child = spawn(SYNCBOX, args, { env: { ...CLEAN_ENV, ...env }, stdio: ['ignore', 'pipe', 'pipe'] });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (d) => (stdout += d));
    child.stderr.on('data', (d) => (stderr += d));
    child.on('error', reject);
    child.on('exit', (code) => resolve({ code, stdout, stderr }));
  });
}

const sha256 = (data) => createHash('sha256').update(data).digest('hex');

describe('syncbox CLI', () => {
  let tmp;
  let server;
  let serverUrl;
  let puts;

  before(async () => {
    tmp = await fs.mkdtemp(path.join(os.tmpdir(), 'syncbox-cli-'));
    server = createServer({ dataDir: path.join(tmp, 'data') });
    puts = 0;
    server.on('request', (req) => req.method === 'PUT' && puts++);
    await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
    serverUrl = `http://127.0.0.1:${server.address().port}`;
  });

  after(async () => {
    server.closeAllConnections();
    await new Promise((resolve) => server.close(resolve));
    await fs.rm(tmp, { recursive: true, force: true });
  });

  async function makeDir(name, files) {
    const dir = path.join(tmp, name);
    for (const [rel, content] of Object.entries(files)) {
      await fs.mkdir(path.dirname(path.join(dir, rel)), { recursive: true });
      await fs.writeFile(path.join(dir, rel), content);
    }
    return dir;
  }

  it('push uploads the directory and reports what it did', async () => {
    const dir = await makeDir('push-basic', { 'cli/one.txt': '1', 'cli/sub/two.txt': '22' });
    const first = await run(['push', dir, '--server', serverUrl]);
    assert.equal(first.code, 0, first.stderr);
    assert.equal(first.stdout, 'uploaded cli/one.txt\nuploaded cli/sub/two.txt\npush: 2 uploaded, 0 already up to date\n');
    assert.equal(first.stderr, '');

    const blobs = await (await fetch(`${serverUrl}/blobs`)).json();
    assert.deepEqual(
      blobs.filter((b) => b.key.startsWith('cli/')).map((b) => [b.key, b.sha256]),
      [['cli/one.txt', sha256('1')], ['cli/sub/two.txt', sha256('22')]],
    );

    const putsBefore = puts;
    const second = await run(['push', dir, '--server', serverUrl]);
    assert.equal(second.code, 0, second.stderr);
    assert.equal(second.stdout, 'push: 0 uploaded, 2 already up to date\n');
    assert.equal(puts, putsBefore);
  });

  it('push takes the server from SYNCBOX_SERVER', async () => {
    const dir = await makeDir('push-env', { 'env.txt': 'from env' });
    const { code, stdout, stderr } = await run(['push', dir], { SYNCBOX_SERVER: serverUrl });
    assert.equal(code, 0, stderr);
    assert.match(stdout, /^uploaded env\.txt$/m);
  });

  it('--server overrides SYNCBOX_SERVER', async () => {
    const dir = await makeDir('push-override', { 'override.txt': 'x' });
    const { code, stderr } = await run(['push', dir, `--server=${serverUrl}`], { SYNCBOX_SERVER: 'http://127.0.0.1:1' });
    assert.equal(code, 0, stderr);
  });

  it('push reports skipped files on stderr', async () => {
    const dir = await makeDir('push-skip', { 'kept.txt': 'k' });
    await fs.symlink('kept.txt', path.join(dir, 'link'));
    const { code, stdout, stderr } = await run(['push', dir, '--server', serverUrl]);
    assert.equal(code, 0, stderr);
    assert.match(stdout, /^uploaded kept\.txt$/m);
    assert.equal(stderr, 'syncbox: skipping link: symbolic link\n');
  });

  it('exits with code 1 and a message when the server is unreachable', async () => {
    const probe = net.createServer();
    const port = await new Promise((resolve) => probe.listen(0, '127.0.0.1', () => resolve(probe.address().port)));
    await new Promise((resolve) => probe.close(resolve));

    const dir = await makeDir('push-unreachable', { 'a.txt': 'a' });
    const { code, stdout, stderr } = await run(['push', dir, '--server', `http://127.0.0.1:${port}`]);
    assert.equal(code, 1);
    assert.equal(stdout, '');
    assert.match(stderr, /^syncbox: cannot reach server http:\/\/127\.0\.0\.1:\d+\/: .*ECONNREFUSED/);
  });

  it('exits with code 1 when the directory does not exist', async () => {
    const { code, stderr } = await run(['push', path.join(tmp, 'no-such-dir'), '--server', serverUrl]);
    assert.equal(code, 1);
    assert.match(stderr, /^syncbox: ENOENT: no such file or directory/);
  });

  for (const command of ['pull', 'status', 'sync']) {
    it(`${command} says it is not implemented yet`, async () => {
      const dir = await makeDir(`not-implemented-${command}`, {});
      await fs.mkdir(dir, { recursive: true });
      const { code, stdout, stderr } = await run([command, dir, '--server', serverUrl]);
      assert.equal(code, 1);
      assert.equal(stdout, '');
      assert.equal(stderr, `syncbox: the ${command} command is not implemented yet; only push is available\n`);
    });
  }

  it('exits with code 2 and usage when --server is missing', async () => {
    const { code, stderr } = await run(['push', tmp]);
    assert.equal(code, 2);
    assert.match(stderr, /server URL is required: pass --server <url> or set SYNCBOX_SERVER/);
    assert.match(stderr, /Usage: syncbox/);
  });

  it('exits with code 2 on an unknown command', async () => {
    const { code, stderr } = await run(['upload', tmp, '--server', serverUrl]);
    assert.equal(code, 2);
    assert.match(stderr, /unknown command: upload/);
  });

  it('prints usage on --help', async () => {
    const { code, stdout } = await run(['--help']);
    assert.equal(code, 0);
    assert.match(stdout, /^Usage: syncbox <command> <dir> --server <url>/);
  });
});
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { after, before, describe, it } from 'node:test';

import { listFiles, sha256File } from '../src/local-files.js';

describe('listFiles', () => {
  let tmp;

  before(async () => {
    tmp = await fs.mkdtemp(path.join(os.tmpdir(), 'syncbox-local-'));
  });

  after(async () => {
    await fs.rm(tmp, { recursive: true, force: true });
  });

  async function makeTree(name, files) {
    const root = path.join(tmp, name);
    for (const [rel, content] of Object.entries(files)) {
      await fs.mkdir(path.dirname(path.join(root, rel)), { recursive: true });
      await fs.writeFile(path.join(root, rel), content);
    }
    await fs.mkdir(root, { recursive: true });
    return root;
  }

  it('lists files recursively, keyed by relative POSIX path, sorted by key', async () => {
    const root = await makeTree('tree', {
      'b.txt': 'b',
      'a/z.txt': 'z',
      'a/deep/er/x.bin': 'x',
      '.hidden': 'h',
      'with space/ünï ?#%.txt': 'u',
    });
    await fs.mkdir(path.join(root, 'empty-dir'));
    const files = await listFiles(root);
    assert.deepEqual(
      files.map((f) => f.key),
      ['.hidden', 'a/deep/er/x.bin', 'a/z.txt', 'b.txt', 'with space/ünï ?#%.txt'],
    );
    for (const { key, path: file } of files) {
      assert.equal(file, path.join(root, ...key.split('/')));
    }
  });

  it('returns nothing for an empty directory', async () => {
    assert.deepEqual(await listFiles(await makeTree('empty', {})), []);
  });

  it('skips symbolic links and special files, reporting each', async () => {
    const root = await makeTree('special', { 'real.txt': 'r', 'sub/inner.txt': 'i' });
    await fs.symlink('real.txt', path.join(root, 'link-to-file'));
    await fs.symlink('sub', path.join(root, 'link-to-dir'));
    await fs.symlink('/etc', path.join(root, 'link-outside'));
    execFileSync('mkfifo', [path.join(root, 'sub', 'pipe')]);

    const skipped = [];
    const files = await listFiles(root, { onSkip: (rel, reason) => skipped.push([rel, reason]) });
    assert.deepEqual(files.map((f) => f.key), ['real.txt', 'sub/inner.txt']);
    assert.deepEqual(skipped.sort(), [
      ['link-outside', 'symbolic link'],
      ['link-to-dir', 'symbolic link'],
      ['link-to-file', 'symbolic link'],
      ['sub/pipe', 'not a regular file'],
    ]);
  });

  it('skips file names that are not valid UTF-8', async () => {
    const root = await makeTree('bad-names', { 'ok.txt': 'ok' });
    const rootBytes = Buffer.from(root);
    await fs.writeFile(Buffer.concat([rootBytes, Buffer.from('/bad-\xff-name', 'latin1')]), 'x');
    await fs.mkdir(Buffer.concat([rootBytes, Buffer.from('/bad-\xfe-dir', 'latin1')]));

    const skipped = [];
    const files = await listFiles(root, { onSkip: (rel, reason) => skipped.push(reason) });
    assert.deepEqual(files.map((f) => f.key), ['ok.txt']);
    assert.deepEqual(skipped, ['file name is not valid UTF-8', 'file name is not valid UTF-8']);
  });

  it('fails for a missing directory or a regular file', async () => {
    await assert.rejects(listFiles(path.join(tmp, 'missing')), { code: 'ENOENT' });
    const file = path.join(tmp, 'plain-file');
    await fs.writeFile(file, 'x');
    await assert.rejects(listFiles(file), { code: 'ENOTDIR' });
  });
});

describe('sha256File', () => {
  it('hashes the file contents', async () => {
    const tmp = await fs.mkdtemp(path.join(os.tmpdir(), 'syncbox-hash-'));
    try {
      const big = Buffer.alloc(3 * 1024 * 1024 + 7, 0xab);
      for (const content of [Buffer.alloc(0), Buffer.from('hello\n'), big]) {
        const file = path.join(tmp, 'f');
        await fs.writeFile(file, content);
        assert.equal(await sha256File(file), createHash('sha256').update(content).digest('hex'));
      }
    } finally {
      await fs.rm(tmp, { recursive: true, force: true });
    }
  });
});
Продолжаем проект Syncbox (тикеты 1-6 — каркас сервера, happy path для PUT/GET блоба, список блобов, удаление блоба, защита от directory traversal, атомарность записи при параллельных PUT — уже сделаны в этом же репозитории). Тикет 7: клиент, команда push.

Полная спецификация — в файлах SYNCBOX-SPEC.md и syncbox-openapi.yaml в корне этого репозитория — прочитай перед началом, если нужно освежить детали.

Нужно реализовать:

- CLI-клиент с исполняемым файлом syncbox (см. раздел «CLI (обязательный контракт)» спецификации) и команду syncbox push <dir> --server <url>: рекурсивно обойти <dir>, посчитать SHA-256 каждого файла, сравнить со списком блобов на сервере (GET /blobs) и загрузить (PUT) файлы, отсутствующие на сервере или отличающиеся от серверной версии по SHA-256. Файлы, идентичные по содержимому серверной версии, повторно не загружать.
- Ключ блоба — относительный POSIX-путь файла внутри <dir> (та же конвенция key, что и на сервере).
- --server обязателен; то же значение можно задать переменной окружения SYNCBOX_SERVER — как описано в спецификации.
- Обёртка запуска: исполняемый файл run-client в корне репозитория, вызываемый как run-client push <dir> --server <url> — форвардит подкоманду и аргументы клиенту. Конвенция описана в разделе «Критерии приёмки» спецификации, без неё клиент не получится проверить автоматическими тестами.
- Клиент, как и сервер, должен исполняться в Docker-контейнере через docker compose, не напрямую на хосте — то же требование раздела «Docker-изоляция», распространённое и на клиент.

Границы этого тикета:

- pull/status/sync — отдельные будущие тикеты (8-10), не входят. run-client должен принимать все четыре подкоманды по интерфейсу (push/pull/status/sync <dir> --server <url>), но реализовывать поведение pull/status/sync не нужно — для них достаточно понятного сообщения о том, что команда пока не реализована, вместо необъяснимого падения.
- Полная обработка сетевых ошибок и частичных сбоев (недоступный сервер, часть файлов не загрузилась) — отдельный будущий тикет (11), не входит. Базовая реакция на явный сбой (например, сервер недоступен) должна быть вменяемой — не проходить молча и не зависать, — но не обязана покрывать весь объём раздела «Коды возврата и ошибки» спецификации (детальный формат отчёта по частичным сбоям, коды возврата под конкретные случаи) — это тикет 11.

Не реализовывай перечисленное выше заранее — не входит в объём этого тикета.

Библиотеки, HTTP-клиент и внутреннее устройство — на твоё усмотрение, как и в предыдущих тикетах.

